from pwn import *

# Connect to the server
conn = remote('rev.chal.csaw.io', 10010)

def read_until_prompt():
    data = conn.recvuntil(b'> ')
    return data.decode()

def send_wish():
    conn.sendline(b'2')
    return read_until_prompt()

def read_balance():
    conn.sendline(b'1')
    return read_until_prompt()

def parse_balance(response):
    try:
        # Extract balance from response
        balance_line = [l for l in response.split('\n') if 'Balance:' in l][0]
        return int(balance_line.split(':')[1].strip())
    except:
        return 0

# Initial read
print(read_until_prompt())

# Main loop - let's try to see how the gacha system works
for i in range(5):
    # Check balance
    balance_resp = read_balance()
    balance = parse_balance(balance_resp)
    print(f"Current balance: {balance}")

    # Try wishing
    wish_resp = send_wish()
    print(f"Wish result {i+1}:")
    print(wish_resp)

conn.close()

